/** @typedef {import("../types.mjs").Finding} Finding */
/** @typedef {import("../types.mjs").RuleContext} RuleContext */
import { readPackagesLock, readPackagesMdVersions, packageIdFromSettingsEntry, LOCK_PATH, PACKAGES_MD_PATH } from "../lib/packages.mjs";

export const id = "PC-18";
export const title = "config/packages.lock.json, docs/PACKAGES.md and config/settings.json agree (three-way)";
export const tags = ["packages"];
export const closes = ["REQ-EXT-28", "REQ-PRV-45", "REQ-PRV-47"];

// config/settings.json is generated by the installer and git-ignored; on a fresh clone only the
// tracked config/settings.default.json exists. Both names appear here so that this rule checks
// the shipped package list before the first install too, instead of silently finding nothing.
const SETTINGS_GENERATED = "config/settings.json";
const SETTINGS_TEMPLATE = "config/settings.default.json";

/**
 * Two directions complete the triangle pc-09 (settings.json ⊆ PACKAGES.md ∖ DENYLIST.md)
 * leaves open, both anchored on config/packages.lock.json — the actual machine-readable
 * allowlist docs/PACKAGES.md's own header says pins live in:
 *   1. every lock entry has a matching, version-agreeing docs/PACKAGES.md section
 *   2. every package settings.json wires is a reviewed, pinned entry in the lock file
 * A lock entry with no settings.json wiring yet is not flagged — most of this repo's
 * packages are reviewed and pinned well before the extension that wires them lands.
 * @param {RuleContext} ctx @returns {Finding[]}
 */
export function run(ctx) {
  const lock = readPackagesLock(ctx);
  if ("error" in lock) return [{ rule: id, file: LOCK_PATH, message: lock.error }];
  if (lock.entries.length === 0) return []; // nothing pinned yet — nothing to reconcile

  /** @type {Finding[]} */
  const findings = [];
  const mdVersions = ctx.exists(PACKAGES_MD_PATH) ? readPackagesMdVersions(ctx) : new Map();

  for (const entry of lock.entries) {
    if (typeof entry?.name !== "string" || typeof entry?.version !== "string") continue;
    const mdEntry = mdVersions.get(entry.name);
    if (!mdEntry) {
      findings.push({
        rule: id,
        file: LOCK_PATH,
        message: `"${entry.name}" is pinned at ${entry.version} but docs/PACKAGES.md has no "## \`${entry.name}\`" section`,
      });
      continue;
    }
    if (mdEntry.version !== entry.version) {
      findings.push({
        rule: id,
        file: PACKAGES_MD_PATH,
        line: mdEntry.line,
        message: `docs/PACKAGES.md states "${entry.name}" ${mdEntry.version} but config/packages.lock.json pins ${entry.version} — the two must agree`,
      });
    }
  }

  const SETTINGS_PATH = ctx.exists(SETTINGS_GENERATED) ? SETTINGS_GENERATED : SETTINGS_TEMPLATE;
  if (ctx.exists(SETTINGS_PATH)) {
    let settings;
    try {
      settings = ctx.readJSON(SETTINGS_PATH);
    } catch (err) {
      findings.push({ rule: id, file: SETTINGS_PATH, message: String(err.message ?? err) });
      return findings;
    }
    const wired = Array.isArray(settings?.packages) ? settings.packages : [];
    const lockNames = new Set(lock.entries.map((e) => e?.name).filter((n) => typeof n === "string"));
    const fileLines = ctx.lines(SETTINGS_PATH);
    for (const pkg of wired) {
      // Same normalisation as PC-09: settings.json wires by local path, the lock is keyed by npm id.
      const npmId = packageIdFromSettingsEntry(pkg);
      if (npmId === null || lockNames.has(npmId)) continue;
      const needle = typeof pkg === "string" ? pkg : npmId;
      const line = fileLines.find((l) => l.text.includes(`"${needle}"`))?.line;
      findings.push({
        rule: id,
        file: SETTINGS_PATH,
        line,
        message: `package "${npmId}" is wired in settings.json but has no entry in config/packages.lock.json — nothing was reviewed or pinned for it`,
      });
    }
  }

  return findings;
}
